import pandas as pd

def clean(df):
    df = df.copy()
    # fix island whitespace / variant
    if 'island' in df.columns:
        df['island'] = df['island'].astype(str).str.strip()
    # fix species case / variant
    if 'species' in df.columns:
        df['species'] = df['species'].astype(str).str.strip()
        df['species'] = df['species'].replace({'chinstrap': 'Chinstrap'})
        df['species'] = df['species'].apply(lambda x: x.title() if isinstance(x, str) else x)
    # ensure numeric columns are numeric
    num_cols = ['bill_length_mm', 'bill_depth_mm', 'flipper_length_mm', 'body_mass_g', 'year']
    for col in num_cols:
        if col in df.columns:
            df[col] = pd.to_numeric(df[col], errors='coerce')
    return df

def answer(df):
    dfc = clean(df)
    # count penguins per island, drop missing keys
    dfc = dfc.dropna(subset=['island'])
    counts = dfc.groupby('island').size()
    allowed = {'Biscoe', 'Dream', 'Torgersen'}
    result = {k: int(v) for k, v in counts.items() if k in allowed}
    return result
